import * as React from 'react';
import {RadialInspectorOverlay,type RadialInspectorOverlayProps} from './radial-overlay';
import {useContextGesture,type ContextGestureOptions} from './context-gesture';
export interface RadialInspectorContextMenuProps extends Omit<RadialInspectorOverlayProps,'open'|'onOpenChange'|'anchorPoint'>,ContextGestureOptions {children:React.ReactNode;open?:boolean;onOpenChange?:(open:boolean)=>void;className?:string}
/** Right-click / touch hold host. Reopening starts at the inner ring. */
export function RadialInspectorContextMenu({children,open:controlled,onOpenChange,className,longPressDelay,movementTolerance,longPress,...props}:RadialInspectorContextMenuProps){const [localOpen,setLocalOpen]=React.useState(false),[anchor,setAnchor]=React.useState<{x:number;y:number}|null>(null);const open=controlled??localOpen;const change=(v:boolean)=>{if(controlled===undefined)setLocalOpen(v);onOpenChange?.(v)};const gesture=useContextGesture(point=>{setAnchor(point);change(true)},{longPressDelay,movementTolerance,longPress});return <><div className={className?`nb-radial-context-trigger ${className}`:'nb-radial-context-trigger'} tabIndex={0} aria-haspopup="dialog" aria-expanded={open} aria-label="Open circular inspector with right-click, touch long-press, or Shift F10" {...gesture}>{children}</div><RadialInspectorOverlay {...props} open={open} onOpenChange={change} anchorPoint={anchor}/></>}
